const OFF_ROWS = [['Dealer gamma, the walls and the flip', '/ticker/SPY'], ['Flow, the tape and off-exchange blocks', '/ticker/SPY'], ['The scanner’s scores and tiers', '/scanner'], ['AI reads', '/ticker/SPY'], ['Option prices, greeks and implied volatility', '/ticker/SPY'], ['The Lab’s instruments', '/lab']];

function liveSection(env) {
  if (env === 'staging') return `<h2 id="data" class="display">What’s live on this site</h2>
    <p><strong>Nothing: this is the demo.</strong> Every screen runs on an authored scenario dated October 7, 2026, and the site makes no calls to Convexa’s API or to any third party. You are signed in to the demo account; your changes stay in this browser until you reset them from the demo bar.</p>
    <div class="ss-live"><div><h3>${icon('sample', 15)}In this demo</h3><table><thead><tr><th>What</th><th>Shaped like</th></tr></thead><tbody>${[['Dealer structure, flow, scores, AI reads', 'the Massive options feed'], ['Rates, positioning, short data', 'Treasury, CFTC and FINRA'], ['Filings and reported figures', 'SEC EDGAR'], ['Research notes', 'six authored samples'], ['Daily bars and indicators', 'computed from sample bars']].map(([a, b]) => `<tr><td>${a}</td><td>${provChip(`Demo · shaped like ${b}`, 'dashed')}</td></tr>`).join('')}</tbody></table></div><div><h3>${icon('activity', 15)}The live site</h3><p class="dline" style="margin: 0; font-size: 13.5px;">The production site runs the public data live — Treasury, CFTC, FINRA, SEC EDGAR, research notes and TradingView’s daily chart — and shows Not live wherever the options feed would be needed.</p><a class="ss-demo t-info" href="https://convexa.pages.dev/methodology#data">Open the live site ${icon('external', 14)}</a></div></div>
    <div>${tagRow('demo', 'Demo · sample data', 'The bar on every page here. Every source chip is dashed and says what the sample is shaped like.')}${tagRow('computed', 'Computed', 'Convexa computed it, here from sample inputs.')}</div>`;
  return `<h2 id="data" class="display">What’s live on this site</h2>
    <p>This site runs without a paid options feed. <strong>Everything built from public records is live</strong>, each with its source and its date. <strong>Everything built from the options chain is not live</strong>: those panels say what they would show and why they are off, and link to the same screen on the demo, where every screen runs on sample data.</p>
    <div class="ss-live"><div><h3>${stateTag('current', 'Live here')}</h3><table><thead><tr><th>What</th><th>Source</th><th>How late</th></tr></thead><tbody>${LIVE_ROWS.map(([a, b, c]) => `<tr><td>${a}</td><td>${b}</td><td>${c}</td></tr>`).join('')}</tbody></table></div><div><h3>${stateTag('notLive', 'Not live here')}</h3><table><thead><tr><th>Needs the options feed</th><th></th></tr></thead><tbody>${OFF_ROWS.map(([a, p]) => `<tr><td>${a}</td><td style="text-align: right;"><a class="t-info" href="${demoUrl(p)}" style="white-space: nowrap;">On the demo →</a></td></tr>`).join('')}</tbody></table></div></div>
    <p>Each panel carries one of these words, with its glyph. Failures add burnt orange; none of them uses green or red.</p>
    <div>${tagRow('current', 'Updated', 'Current to its source, with the source’s date. Never a live dot.')}${tagRow('delayed', 'Delayed by source', 'The source publishes late on a schedule; the tag says by how much.')}${tagRow('computed', 'Computed', 'Convexa computed it from public inputs it names.')}${tagRow('thirdParty', 'Live · TradingView', 'A third party draws it from its own data; Convexa reads nothing from it.')}${tagRow('notLive', 'Not live', 'Needs the paid options feed this site doesn’t run.')}${tagRow('stale', 'Last good copy', 'This cycle failed; the earlier copy shows dimmed, with when it was fetched.')}${tagRow('unavailable', 'Source down', 'The source didn’t answer and nothing is kept: unknown, not empty.')}${tagRow('error', 'Couldn’t load', 'Our request failed. The panel says why and offers Try again.')}${tagRow('notConfigured', 'Not set up', 'This site lacks a setting, such as the SEC’s required contact line.')}${tagRow('off', 'Off', 'Switched off on purpose.')}${tagRow('locked', 'Sign in', 'Behind the private-testing wall; sign-ups are closed.')}${tagRow('sample', 'Illustrative sample', 'Only on the landing page’s illustrations. Never market data.')}</div>`;
}
const P = (t) => `<p>${t}</p>`;
const PM = (t) => `<p style="font-size: 14px;">${t}</p>`;
const tbl = (head, rows) => `<table class="ss-tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c, i) => `<td${i === 1 && head[1] === 'Max' ? ' class="m"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const VOCAB = [['—', 'no value on this snapshot — a plain dash, never a fake zero'], ['unavailable', 'an input failed or is missing this cycle'], ['not given', 'the read did not answer this field'], ['not set', 'you supplied no risk block — the one on this list you can clear yourself, by typing one'], ['size not suggested', 'the risk block is present; the model returned no size'], ['unrecognized', 'the read answered a conviction outside low / medium / high; Convexa will not repeat what it cannot place'], ['not recorded', 'the saved record never held this fact, so there is nothing to show'], ['not provided', 'the feed did not send this field — the source withheld it, not us'], ['no basis', 'no cost basis is on file, so a cost-based figure cannot be derived; the dollar figure beside it is still real']];
function methodArticle(env) {
  const h = (id, t) => `<h2 id="${id}" class="display">${t}</h2>`;
  return `<article><div style="display: flex; flex-direction: column; gap: 10px;"><h1 class="display">How Convexa works</h1><p>What the numbers mean, how often they update, and where the read is weak. Not a pitch deck — the assumptions behind the desk.</p></div>
    ${liveSection(env)}
    ${h('two-data-speeds', 'Two data speeds — do not mix them')}${P('Prices on the live tape update from a stream. Structure — score, tier, flip, walls, GEX, setups — refreshes on a slower poll (about a minute on a ticker desk, about every three minutes across the scanner, sooner for names that just moved). The scanner and ticker say “Structure as-of …” for that path.')}${P('When the live stream drops, live cells dim and say offline. Structure stays readable at its last snapshot. A quiet tape is not a blank desk.')}
    ${h('dealer-structure', 'Dealer structure — walls, flip, GEX')}${P('The core read is options dealer positioning: call and put walls, the gamma flip, and net GEX across strikes in your selected expiration window. Those levels come from the option chain snapshot, not from inventing direction on the front end.')}${P('GEX and walls are computed at a GEX spot basis (often the session close when the market is closed, the live mid during regular hours for the engine’s phase rules). The desk always labels that basis so a level is never confused with the live tape price.')}${P('Raw dollar GEX sizes exposure for a fixed 1% spot shock. Vol-norm GEX divides that magnitude by ATM IV (or 30-day HV if ATM IV is missing) so readings stay comparable when vol is high or low. Walls and the flip stay raw strike levels. Vol-norm GEX is not a scoring input.')}
    ${h('flip-vs-walls', 'Flip vs walls — different gamma bases')}${P('Call wall and put wall pick the strikes with the largest positive and negative dealer gamma using the vendor’s per-contract gamma and a dealer-sign open-interest convention (calls short, puts long as the default dealer book). That is a snapshot convention, not a measured inventory — real desks can and do differ.')}${P('Gamma flip is not “the wall’s midpoint”. It is the zero-crossing of the analytic net-GEX curve across strikes, where hedging flips from dampening to amplifying. Walls can sit far from the flip when the gamma profile is skewed.')}${PM('Limitations: vendor gamma can lag or gap on thin names; OI sign is an assumption; levels are only as good as the chain snapshot. When gamma or OI is missing the cell says unavailable — we do not invent a wall.')}
    ${h('score-and-tier', 'Score and tier')}${P('The score is a sum of plain components, capped twice. The four base components below are summed and capped at 100; the dark-pool confluence bonus is added after that cap and capped again, so no score ever exceeds 100:')}${tbl(['Component', 'Max', 'What it reads'], [['Proximity to walls / flip', '40', 'how close the mid sits to a level that matters'], ['|IV/HV − 1| stretch', '25', 'how far implied vol sits from realised'], ['Active setups', '25', 'rule-based reads currently firing'], ['Flip transition', '10', 'the mid sits within 1% of the gamma flip'], ['Dark-pool confluence', '6', 'optional · off-exchange prints near a level']])}${PM('Honest scope: today’s score does not consume vol-normalized GEX or the IV-rank band. Those are advisory context on the desk only.')}
    ${h('advisory-reads', 'Advisory reads')}${P('Projected dealer flow (charm, vanna), market context (trend, profile shape, flow vs positioning, ATR), IV rank, the straddle-implied move, fresh positioning and off-exchange blocks sit in the context band. They carry their own basis and as-of, and none of them feeds the score.')}
    ${h('ai-read-and-grounding', 'AI read and grounding')}${P('A read runs on your own key, pinned to one snapshot, framed by your persona and capped by your risk inputs. It answers trade or no trade first, then max risk, invalidation, entry and target. Figures that trace to Convexa render in mono; a figure the model asserted but that could not be traced renders in body type.')}${P('A “no trade” read is a complete, correct answer — not an error and not a failed request.')}${PM('What leaves the machine, on demand, is the computed snapshot, the candidate contracts, your two risk numbers, the open-positions digest for the ticker, the persona prompt and the field glossary. Open “What’s sent to the AI” on any ticker, or “View what’s sent” in Settings → Risk inputs, to read the exact payload first.')}
    ${h('simulation', 'Simulation')}${P('Simulated trades and orders are paper. Fills model at the mid with no slippage and no partial fills; a sim order triggers and fills only while a live stream for that ticker is open in your browser.')}
    ${h('where-the-read-is-weak', 'Where the read is weak')}${P('Evidence is strongest on liquid index and megacap names. Thin single names can show structure that is noise. Missing chain data, a failed symbol or a building first pass shows as unavailable or building — never a fabricated zero.')}
    ${h('what-convexa-never-does', 'What Convexa never does')}${P('No real order path: nothing here places, changes or cancels a broker order. No guarantee: structure is context for a plan, not a price forecast and not a trade command. AI reads are advisory and require an explicit accept into the sim book.')}
    ${h('vocabulary', 'Vocabulary')}${P('This is the complete set: the product renders no other word in place of a number.')}${tbl(['Literal', 'Means'], VOCAB)}
    <p style="font-size: 13px; padding-top: 16px; border-top: 1px solid var(--line);">Convexa is an analysis tool. Simulated positions are paper. A connected brokerage is read-only — Convexa never places, changes, or cancels an order. Not investment advice.</p>
    <div style="display: flex; flex-wrap: wrap; gap: 12px;"><a href="/ticker" class="btn primary">Open free Ticker</a><a href="/scanner" class="btn secondary">Open Scanner</a><a href="/" class="btn ghost">Back to home</a></div></article>`;
}
export function methodologyBoard(env) {
  return ({ minHeight = 0, scheme = 'dark' } = {}) => sitePage({ env, scheme, minHeight, label: 'Methodology', main: `<div class="wrap doc"><nav aria-label="On this page">${TOC.map(([id, t], i) => `<a href="#${id}"${i === 0 ? ' aria-current="true"' : ''}>${t}</a>`).join('')}</nav>${methodArticle(env)}</div>` });
}

