/** The post's first figure, redrawn neutral (P-9, P-11): a schematic, not a chart of any market. */
function levelsSchematic(h = 220) {
  const pts = [[0, -40], [8, -55], [16, -70], [24, -62], [32, -40], [40, -12], [44, 0], [52, 30], [60, 58], [68, 72], [76, 64], [84, 44], [92, 26], [100, 18]];
  return plot({ height: h, pl: 20, pr: 20, prn: 12, pt: 28, pb: 30, ends: false, keyboard: false, x: { min: 0, max: 100, ticks: [{ v: 0, label: 'lower strikes', align: 0 }, { v: 100, label: 'higher strikes', align: 1 }] }, y: { min: -90, max: 95, ticks: [] }, hlines: [{ v: 0, kind: 'zero' }], series: [{ points: pts, role: 'emph', width: 2.5 }], segs: [{ x0: 16, y0: -90, x1: 16, y1: 95, role: 'ctx', width: 1.2, dash: '4 4', essential: false }, { x0: 44, y0: -90, x1: 44, y1: 95, role: 'emph', width: 1.5, dash: '4 4', essential: false }, { x0: 68, y0: -90, x1: 68, y1: 95, role: 'ctx', width: 1.2, dash: '4 4', essential: false }], pointLabels: [{ x: 16, y: 95, text: 'Put wall · −γ' }, { x: 44, y: 95, text: 'Flip' }, { x: 68, y: 95, text: 'Call wall · +γ' }, { x: 28, y: 4, text: 'zero', minor: true }], aria: 'Schematic: a net dealer gamma curve across strikes, most negative at the put wall, crossing zero at the flip, most positive at the call wall.' });
}
const BLOG_INTRO = 'Dealer structure, score honesty, and the two clocks on the desk: the longer form of the Methodology page.';
export function blogIndexBoard(env) {
  return ({ minHeight = 0, scheme = 'dark' } = {}) => sitePage({ env, scheme, minHeight, label: 'Blog', main: `<div class="wrap" style="padding-top: 40px; display: flex; flex-direction: column; gap: 24px; max-width: 1100px;"><div style="display: flex; flex-direction: column; gap: 10px;"><span class="caps">Blog</span><h1 class="display" style="margin: 0; font-size: clamp(32px, 3.4vw, 44px);">How we read structure</h1><p class="steel" style="margin: 0; max-width: 62ch; font-size: 16px; line-height: 1.6;">${BLOG_INTRO}</p></div>
    <a href="/blog/how-we-read-dealer-structure.html" class="hd-p" style="text-decoration: none; color: inherit !important; display: grid; grid-template-columns: repeat(auto-fit, minmax(min(320px, 100%), 1fr)); gap: 24px; align-items: center; padding: 24px;"><div style="display: flex; flex-direction: column; gap: 10px; min-width: 0;"><span class="stag k-solid" style="align-self: flex-start;">Methodology</span><span class="display" style="font-size: 28px; line-height: 1.15;">How We Read Dealer Structure</span><span class="dline" style="font-size: 14.5px;">Walls, the gamma flip, GEX, score, and two data speeds — what Convexa actually computes, on what basis, and where the read is weak.</span><span class="t-info" style="display: inline-flex; gap: 6px; align-items: center; font-weight: 600; font-size: 14px;">Read the post ${icon('arrow', 14)}</span></div><figure class="ss-schem" style="margin: 0;">${levelsSchematic(170)}<figcaption>Schematic — not a chart of any market.</figcaption></figure></a>
    <p class="dline" style="margin: 0;">One post so far. New posts appear here; drafts are never listed.</p></div>` });
}
export function blogPostBoard(env) {
  return ({ minHeight = 0, scheme = 'dark' } = {}) => sitePage({ env, scheme, minHeight, label: 'How We Read Dealer Structure', main: `<div class="wrap"><article class="ss-post" style="margin: 0 auto;">
    <a href="/blog" class="t-info" style="display: inline-flex; align-items: center; gap: 6px; min-height: 24px; font-size: 14px; text-decoration: none;">← All posts</a>
    <div class="meta"><span class="stag k-solid">Methodology</span><span>Blog · How we read structure</span></div>
    <h1 class="display">How We Read Dealer Structure</h1>
    <p style="font-size: 18px; color: var(--phosphor);">Walls, the gamma flip, GEX, score, and two data speeds — what Convexa actually computes, on what basis, and where the read is weak.</p>
    <h2 class="display">Not a crystal ball</h2>
    <p>Convexa is an <strong>analysis desk</strong>, not a forecast machine. The numbers you see are a structured read of <strong>options dealer positioning</strong> from a chain snapshot: call and put walls, the gamma flip, net GEX across strikes, and a plain additive opportunity score.</p>
    <p>We do not invent direction on the frontend. Structure is computed on the server from the option chain. The browser maps labels and layouts — it does not re-score a scan row into a different truth.</p>
    <blockquote>Simulated trades are paper. A connected brokerage is read-only. Nothing here places, changes, or cancels a real order. This is not investment advice.</blockquote>
    <h2 class="display">The objects on the desk</h2>
    <p>Three levels matter most on liquid names:</p>
    <ol><li><strong>Call wall</strong> — the strike with the largest <strong>positive</strong> dealer gamma under our open-interest sign convention.</li><li><strong>Put wall</strong> — the strike with the largest <strong>negative</strong> dealer gamma under the same convention.</li><li><strong>Gamma flip</strong> — the zero-crossing of the <strong>analytic net-GEX curve</strong> across strikes: where hedging behavior flips from dampening to amplifying moves.</li></ol>
    <figure class="ss-schem">${levelsSchematic(240)}<figcaption>Call wall, put wall and gamma flip on a net-GEX curve. Schematic — not a chart of any market. The sign is carried by position: above the zero line, dealers long gamma; below, short.</figcaption></figure>
    <p>Walls and flip are related, not the same object. A skewed gamma profile can put walls far from the flip. Treat the flip as a regime boundary and the walls as concentrated gamma levels — not as a single “support/resistance” cartoon.</p>
    <h2 class="display">Spot basis: which price the structure sits on</h2>
    <p>GEX and walls are computed at a <strong>GEX spot basis</strong> — often the session close when the market is closed, the live mid during regular hours. The ticker always labels that basis so a structure level is never confused with the live tape price.</p>
    <h2 class="display">Two data speeds — do not mix them</h2>
    <p><strong>Structure</strong> — score, tier, flip, walls, GEX, setups — refreshes on a slower poll. The scanner and ticker say <strong>“Structure as-of …”</strong> for that path on purpose. When the live stream drops, live tiles dim and say offline; structure tiles stay readable at their last snapshot.</p>
    <h2 class="display">Want the short in-product version?</h2>
    <p>The product page <a href="/methodology">How Convexa works</a> is the same spine, kept next to the desk. This post is the longer, public version of that honesty.</p>
    </article></div>` });
}

