const opsBar = (path, chips = '') => `<div class="ss-ops">${wordmark(14)}<span class="stag k-solid">operator</span><span class="mono steel" style="font-size: 12px;">${path}</span>${chips}<span style="flex: 1;"></span><span class="dline only-wide">Read-only · unlinked · off the trader shell</span></div>`;
